document.addEventListener('click',e=>{if(!app||sv!='igp'||!e.target.closest('[data-igpf]'))return;const pv=NS[NS.length-2];if(pv&&pv.sv=='ig'){e.stopPropagation();e.preventDefault();history.back()}},true);
const _co=closeApp;closeApp=function(){if(!ap&&NS.length){const n=NS.length;NS.length=0;ign=1;history.go(-n)}last='';_co()};
addEventListener('popstate',()=>{if(ign){ign=0;return}
 if(kbo||document.querySelector('#ph .al,#ph .cl,#ph .lpo')){closeKb();document.querySelectorAll('#ph .al,#ph .cl,#ph .lpo').forEach(e=>e.remove());ign=1;history.forward();return}
 if(!app)return;const was=sv;NS.pop();const t=NS[NS.length-1];ap=1;
 try{if(!t){closeApp()}else{app=t.app;sv=t.sv;cur=t.cur;bf=t.bf;last=key(t);if(was=='igp'||t.sv=='igp'){page(1);igFade()}else page()}}finally{ap=0}});
document.addEventListener('click',e=>{if(!app||!e.target.closest('[data-b]'))return;if(sv=='saf'&&sq)return;if(NS.length){e.stopPropagation();history.back()}},true);
document.addEventListener('click',e=>{const b=e.target.closest('.bn');if(!b||b.dataset.sx!=null)return;const n=b.querySelector('.nh span'),x=ch.find(a=>n&&a.n==n.textContent.trim())||ch[0];
 b.remove();u=0;closeKb();if(!app){const el=$('#hm [data-o="msg"]');if(!el)return;openApp('msg',el)}
 else if(app!='msg'){/* dari app lain (mis. IG): riwayat diganti jadi Daftar Chat > Chat, jadi Kembali tidak balik ke app asal */
  const n=NS.length,cs={app:'msg',sv:'chat',cur:x.id,bf:''};
  NS.length=0;NS.push({app:'msg',sv:'msg',cur:null,bf:''},cs);
  if(n>2){ign=1;history.go(-(n-2))}else for(let i=n;i<2;i++)history.pushState({n:i+1},'');
  app='msg';sv='chat';cur=x.id;bf='';last=key(cs);ap=1;try{page()}finally{ap=0}return}
 sv='chat';cur=x.id;page()},true);
