/* geser dari pojok kiri/kanan layar = kembali (selain gestur kembali bawaan HP) */
(function(){let s=null,fired=0;const ph=()=>document.getElementById('ph');
function go(){fired=1;s=null;window._eb=Date.now();if(window.PN&&PN()){try{tone(900,.03,.02)}catch(_){}window._closeP();return}if(!app){if(window.GA&&GA()){try{tone(900,.03,.02)}catch(_){}window._closeA()}return}{const lp=document.querySelector('#ph .lpo');if(lp){lp.remove();return}}if(kbo){try{tone(900,.03,.02)}catch(_){}closeKb();return}if(document.querySelector('#ph .cl,#ph .al,#ph .en'))return;const bk=document.querySelector('#ap [data-b]');try{tone(900,.03,.02)}catch(_){}if(bk)bk.click();else back()}
function chk(e){if(!s||fired)return;const dx=(e.clientX-s.x)*s.d,dy=Math.abs(e.clientY-s.y);if(dx>=50&&dy<=dx*.8)go()}
addEventListener('pointerdown',e=>{s=null;fired=0;if((!app&&!(window.GA&&GA())&&!(window.PN&&PN()))||(e.pointerType=='mouse'&&e.button!==0))return;const r=ph().getBoundingClientRect();if(e.clientY<r.top||e.clientY>r.bottom)return;const z=Math.max(44,Math.min(64,r.width*.14)),L=e.clientX-r.left,R=r.right-e.clientX;if(L>=-20&&L<=z)s={x:e.clientX,y:e.clientY,d:1};else if(R>=-20&&R<=z)s={x:e.clientX,y:e.clientY,d:-1}},true);
addEventListener('pointermove',chk,true);
addEventListener('pointerup',e=>{chk(e);s=null},true);
addEventListener('pointercancel',()=>{s=null},true);
/* cadangan lewat touch events, kalau browser HP tidak mengirim pointer events di pinggir layar */
addEventListener('touchstart',e=>{if(fired&&s===null&&e.touches.length>1)return;const t=e.touches[0];if(!t||s)return;fired=0;if(!app)return;const r=ph().getBoundingClientRect();if(t.clientY<r.top||t.clientY>r.bottom)return;const z=Math.max(44,Math.min(64,r.width*.14)),L=t.clientX-r.left,R=r.right-t.clientX;if(L>=-20&&L<=z)s={x:t.clientX,y:t.clientY,d:1};else if(R>=-20&&R<=z)s={x:t.clientX,y:t.clientY,d:-1}},{capture:true,passive:true});
addEventListener('touchmove',e=>{const t=e.touches[0];if(t)chk(t)},{capture:true,passive:true});
addEventListener('touchend',()=>{s=null},true);
})();
